from abc import ABC, abstractmethod


class Notification(ABC):
    @abstractmethod
    def send(self, user, message): ...


class EmailNotification(Notification):
    def send(self, user, message):
        send_mail("Notification", message, "noreply@example.com", [user.email])


class SMSNotification(Notification):
    def send(self, user, message):
        sms_client.send(user.phone, message)


class PushNotification(Notification):
    def send(self, user, message):
        push_client.send(user.device_token, message)


class NotificationFactory:
    _mapping = {
        "email": EmailNotification,
        "sms": SMSNotification,
        "push": PushNotification,
    }

    @classmethod
    def create(cls, kind):
        klass = cls._mapping.get(kind)
        if not klass:
            raise ValueError(f"نوع نامعتبر: {kind}")
        return klass()


# استفاده
notification = NotificationFactory.create(user.notification_preference)
notification.send(user, "سفارش شما ثبت شد")
